    return true;
  }).join("\n").replace(/(`+)([^\n]*?)\1/g, "");
  return new Set([...visible.matchAll(/!\[\[([^\]\n|]+)(?:\|[^\]\n]*)?\]\]/g)].map(match => embedTargetKey(match[1]!)));
}

function embedTargetKey(value: string): string {
  try { value = decodeURIComponent(value); } catch { /* Keep literal percent signs in asset names. */ }
  return value.replace(/\\/g, "/").replace(/^\.\//, "").normalize("NFC").toLowerCase();
}

/** Figures placed in the lesson stay there; remaining captures are optional references. */
export function supplementalSourceFigureLines(config: ScholarConfig, book: ScholarBook, notePath: string, snapshots: ScholarSnapshot[], lesson: string): string[] {
  const embedded = nativeEmbedTargets(lesson);
  const supplemental = snapshots.filter(snapshot => {
    const assetPath = snapshotAssetPath(config, book, snapshot);
    const candidates = [snapshot.assetFile, relative(resolve(notePath, ".."), assetPath), relative(config.obsidianRoot, assetPath)];
    return !candidates.some(candidate => embedded.has(embedTargetKey(candidate)));
  });
  return collapsedRecord("Source references", sourceFigureLines(config, book, notePath, supplemental));
}

/** Only explicit source figure labels establish association; page proximity does not. */
export function referencedFigureLines(config: ScholarConfig, book: ScholarBook, notePath: string, text: string, snapshots: ScholarSnapshot[]): string {
  const labels = new Set([...text.matchAll(/\b(?:Figure|Fig\.)\s+(\d+(?:[.\-–]\d+)*[a-z]?)(?!\w|[.\-–]\d)/gi)].map(match => match[1]!.toLowerCase().replace(/–/g, "-")));
  const seen = new Set<string>();
  return snapshots.flatMap(snapshot => {
    const label = /\b(?:Figure|Fig\.)\s+(\d+(?:[.\-–]\d+)*[a-z]?)(?!\w|[.\-–]\d)/i.exec(snapshot.caption)?.[1]?.toLowerCase().replace(/–/g, "-");
    if (!label || !labels.has(label) || seen.has(snapshot.assetFile) || text.includes(snapshot.assetFile)) return [];
    seen.add(snapshot.assetFile);
    return [wikiEmbed(notePath, snapshotAssetPath(config, book, snapshot), 640), "", markdownText(snapshot.caption), "", `*Source: ${markdownText(book.source.fileName)} · PDF viewer page ${snapshot.page}.*`, ""];
  }).join("\n");
}

export function assessmentSummaryLine(attempt: AssessmentAttempt): string {
  const source = attempt.grounding?.sourcePages.length
    ? ` · PDF ${attempt.grounding.sourcePages.length === 1 ? "page" : "pages"} ${attempt.grounding.sourcePages.join(", ")}` : "";
  return `- **${titleCase(attempt.kind)}** — ${readableOutcome(attempt.outcome)}${source}`;
}

export function pendingQuestionLines(attempts: AssessmentAttempt[]): string[] {
  return attempts.flatMap((attempt, index) => attempt.outcome !== "pending" ? [] : [
    ...questionLines(attempt, index), "", "*Awaiting response*", "",
  ]);
}

export function assessmentRecordLines(attempts: AssessmentAttempt[], _title = "Assessment record"): string[] {
  // Each completed prompt stays next to its answer. Pending questions follow
  // the history at the end of the note and retain their original numbering.
  const history = attempts.flatMap((attempt, index) => attempt.outcome === "pending" ? [] : [{ attempt, index }]);
  return history.flatMap(({ attempt, index }, position) => [
    ...(position ? ["", "---", ""] : []), ...questionLines(attempt, index), "", ...attemptAnswerLines(attempt), "",
  ]);
}

/** Learn and Tutor deliberately share the complete question/feedback layout. */
export function assessmentQuestionBlock(attempts: AssessmentAttempt[]): string[] {
  return block("## Questions", [...assessmentRecordLines(attempts), ...pendingQuestionLines(attempts)]);
}

export function passedCheckKinds(section: ScholarSection): Set<AssessmentKind> {
  return new Set(section.requiredChecks.filter((kind) => latestAttemptForKind(section, kind)?.outcome === "pass"));
}

export function renderSection(config: ScholarConfig, book: ScholarBook, chapter: ScholarChapter, section: ScholarSection): string {
  const notePath = sectionNotePath(config, book, chapter, section);
  const chapterLabel = chapter.number ? `Chapter ${chapter.number}: ${chapter.title}` : chapter.title;
  const covered = new Set(section.coveredObjectives);
  const remaining = section.status === "complete" || section.status === "not-started" ? [] : sectionCompletionBlockers(section);
  const answered = Math.min(answeredQuickQuestions(section), QUICK_QUESTIONS);
  const pendingChecks = section.status === "complete" ? 0 : QUICK_QUESTIONS - answered;
  const checks = section.status === "not-started" ? [] : [`Short questions answered: ${answered} of ${QUICK_QUESTIONS}`];
  const lessonProgress = remaining.includes("complete saved instructional lesson") ? "Lesson in progress" : "Lesson saved";
  // The Learning record already reports short-question progress.
  // Keep any other blockers inspectable without repeating long objectives above the lesson.
  const otherRemaining = remaining.filter(item => !/^(?:conceptual|application|computation|discrimination) evidence for: /.test(item) && !/more short questions?$/.test(item));
  const objectives = section.objectives.length ? [
    "| Objective | Teaching coverage |", "| --- | --- |",
    ...section.objectives.map((objective) => `| ${tableText(objective)} | ${covered.has(objective) ? "Taught" : "Not yet taught"} |`),
  ] : [];
  const authored = transcriptBlock(section.transcript || [], section.attempts).trim();
  const lesson = authored ? authored.split("\n") : [];
  const summary = uniqueSupplementLines(section.synthesis ? [section.synthesis] : [], lesson);
  const keyPoints = uniqueSupplementLines(section.keyPoints, [...lesson, ...summary]);
  const pitfalls = uniqueSupplementLines(section.misconceptions, [...lesson, ...summary, ...keyPoints]);
  const current = book.currentSectionId === section.id;
  const commitWarnings: string[] = [];
  if (section.lessonCommit && section.learnQuality?.reviews) {
    for (const review of section.learnQuality.reviews) {
      if (review.failure) {
        commitWarnings.push(`> [!warning] Not independently reviewed: ${review.role} (${review.failure.code})`);
      }
      if (review.role === "visual" && review.findings.some(f => f.issue === "Figures were not visually checked (text-only model).")) {
        commitWarnings.push("> [!warning] Figures were not visually checked (text-only model).");
      }
    }
  }
  const lessonLines = commitWarnings.length ? [...commitWarnings, "", ...lesson] : lesson;
  const content = [
    ...(lessonLines.length ? block("## Lesson", lessonLines) : [section.synthesis?.trim()
      ? "A recap is saved below. The full explanation has not been saved yet."
      : "This section is ready. The lesson will appear as you work through it.", ""]),
    ...supplementalSourceFigureLines(config, book, notePath, section.snapshots || [], authored),
    ...collapsedRecord("Recap and pitfalls", [
      ...block("### Section summary", summary),
      ...block("### Key points", keyPoints.map((point) => `- ${point}`)),
      ...block("### Common pitfalls", pitfalls.map((point) => `- ${point}`)),
    ]),
    ...collapsedRecord("Learning record", [
      ...block("### Learning objectives", objectives),
      ...block("### Understanding checks", checks),
      ...block("### Remaining work", otherRemaining.map(item => `- ${markdownText(item)}`)),
    ]),
    ...assessmentQuestionBlock(section.attempts),
  ];
  return generatedDocument(frontmatter([
    "type: scholar-section", `book_id: ${yaml(book.id)}`, `chapter_id: ${yaml(chapter.id)}`, `section_id: ${yaml(section.id)}`,
    `status: ${yaml(section.status)}`, `current: ${current}`, `created: ${yaml(section.createdAt)}`, `updated: ${yaml(section.updatedAt)}`,
  ]), [
    statusCallout(statusLabel(section.status), [
      current ? "Current section" : "",
      pageRange(section.startPage, section.endPage),
      section.status === "complete" ? "Section complete · reopen for practice anytime"
        : pendingChecks ? `${pendingChecks} short ${pendingChecks === 1 ? "question" : "questions"} remaining` : lessonProgress,
    ].filter(Boolean).join(" · ")), "",
    wikiLink(notePath, chapterNotePath(config, book, chapter), chapterLabel), "",
    ...(content.some((line) => line.trim()) ? content : ["This section is ready. Notes will appear as you work through it."]),
  ].join("\n"));
}

